package ru.cherdakmd.diamondshop;

import org.junit.jupiter.api.Test;
import java.nio.file.*;
import static org.junit.jupiter.api.Assertions.*;

class TradeAmountsTest {
    @Test void canBuyOneItemEvenWhenReferenceLotIsAStack(){assertEquals(1,TradeAmounts.quote(64,3,1,true));assertEquals(2,TradeAmounts.quote(64,3,32,true));}
    @Test void sellingBelowOneDiamondIsAPreviewOnly(){assertEquals(0,TradeAmounts.quote(64,3,21,false));assertEquals(1,TradeAmounts.quote(64,3,22,false));assertEquals(22,TradeAmounts.minimumSale(64,3));}
    @Test void highValueGoodsSellIndividually(){assertEquals(1,TradeAmounts.minimumSale(4,9));assertEquals(2,TradeAmounts.quote(4,9,1,false));assertEquals(3,TradeAmounts.quote(4,9,1,true));}
    @Test void everyFullLotRetainsItsOldWholePrice(){for(int batch:new int[]{1,2,8,32,64,128,256,512,1024,2304})for(long p:new long[]{1,3,17,1000})for(int lots=1;lots*batch<=2304;lots++){assertEquals(p*lots,TradeAmounts.quote(batch,p,(long)batch*lots,true));assertEquals(p*lots,TradeAmounts.quote(batch,p,(long)batch*lots,false));}}
    @Test void priceNeverUsesDoublesAndRejectsOverflowOrOversize(){assertEquals(WholeTrades.MAX,TradeAmounts.quote(2304,WholeTrades.MAX,2304,true));assertEquals(-1,TradeAmounts.quote(1,WholeTrades.MAX,2,true));assertEquals(-1,TradeAmounts.quote(64,3,Long.MAX_VALUE,true));assertEquals(-1,TradeAmounts.quote(64,3,2305,true));}
    @Test void invalidInputsAreNeverFreeTrades(){for(int batch:new int[]{-1,0,2305,Integer.MAX_VALUE})assertEquals(-1,TradeAmounts.quote(batch,3,1,true));for(long p:new long[]{-1,0,WholeTrades.MAX+1,Long.MAX_VALUE}){assertEquals(-1,TradeAmounts.quote(64,p,1,true));assertEquals(0,TradeAmounts.minimumSale(64,p));}assertEquals(-1,TradeAmounts.quote(64,3,0,false));}
    @Test void saleAllRetainsItemsThatDoNotIncreaseRevenue(){assertEquals(22,TradeAmounts.saleAll(64,3,42,100));assertEquals(43,TradeAmounts.saleAll(64,3,63,100));assertEquals(64,TradeAmounts.saleAll(64,3,64,100));assertEquals(0,TradeAmounts.saleAll(64,3,21,100));}
    @Test void saleAllRespectsDailyOrBankHeadroomWithoutTakingAFreeRemainder(){assertEquals(22,TradeAmounts.saleAll(64,3,64,1));assertEquals(43,TradeAmounts.saleAll(64,3,64,2));assertEquals(0,TradeAmounts.saleAll(1,2,64,1));assertEquals(0,TradeAmounts.saleAll(64,3,64,0));}
    @Test void maximumSelectionNeverExceedsStorageOrBudget(){assertEquals(2304,TradeAmounts.saleAll(1,1,Long.MAX_VALUE,Long.MAX_VALUE));assertEquals(1,TradeAmounts.saleAll(1,WholeTrades.MAX,2304,WholeTrades.MAX));assertEquals(0,TradeAmounts.saleAll(0,1,64,100));}
    @Test void saleAllIsOptimalAndKeepsTheSmallestQuantityForThatIncome(){for(int batch:new int[]{1,2,7,16,64,128})for(long price:new long[]{1,2,3,9,63,129})for(int available=1;available<=80;available++)for(long budget:new long[]{1,2,7,100}){int q=TradeAmounts.saleAll(batch,price,available,budget);long income=q==0?0:TradeAmounts.quote(batch,price,q,false);assertTrue(q<=available);assertTrue(income<=budget);if(q>1)assertTrue(TradeAmounts.quote(batch,price,q-1,false)<income);for(int candidate=1;candidate<=available;candidate++){long alternative=TradeAmounts.quote(batch,price,candidate,false);if(alternative<=budget)assertTrue(alternative<=income);}}}
    @Test void splittingBuyOrSaleDoesNotCreateRoundingProfit(){for(int batch:new int[]{1,7,64,256})for(long bid:new long[]{1,3,17,500})for(int a=1;a<=60;a+=3)for(int b=1;b<=60;b+=5){long buy=TradeAmounts.quote(batch,bid+1,a+b,true),sell=TradeAmounts.quote(batch,bid,a+b,false);assertTrue(buy>=sell);assertTrue(TradeAmounts.quote(batch,bid+1,a,true)+TradeAmounts.quote(batch,bid+1,b,true)>=buy);assertTrue(TradeAmounts.quote(batch,bid,a,false)+TradeAmounts.quote(batch,bid,b,false)<=sell);}}
    @Test void minimumIsExactAtBothSidesOfTheOneDiamondBoundary(){for(int batch=1;batch<=2304;batch++)for(long price:new long[]{1,2,3,9,64,1000000000}){int q=TradeAmounts.minimumSale(batch,price);assertTrue(TradeAmounts.quote(batch,price,q,false)>=1);if(q>1)assertEquals(0,TradeAmounts.quote(batch,price,q-1,false));}}
    @Test void quantityAdjustmentsCannotWrapOrEscapeTheLimit(){assertEquals(1,TradeAmounts.adjust(1,-64));assertEquals(2304,TradeAmounts.adjust(2304,64));assertEquals(2304,TradeAmounts.adjust(Integer.MAX_VALUE,Integer.MAX_VALUE));assertEquals(1,TradeAmounts.adjust(Integer.MIN_VALUE,Integer.MIN_VALUE));assertEquals(17,TradeAmounts.adjust(16,1));}
    @Test void zeroQuoteIsRejectedBeforeAnyInventoryPlanOrJournal()throws Exception{String s=Files.readString(Path.of("src/main/java/ru/cherdakmd/diamondshop/ShopService.java"));assertTrue(s.indexOf("if(money==0)")<s.indexOf("var before = copy("));assertTrue(s.indexOf("if(money==0)")<s.indexOf("store.prepare(t,item"));assertTrue(s.contains("TradeAmounts.selectSale(batch,bid"));assertFalse(s.contains("long units = batches * batch"));}
    @Test void selectionUsesFrozenQuoteExplicitConfirmationAndViewIdentity()throws Exception{String s=Files.readString(Path.of("src/main/java/ru/cherdakmd/diamondshop/ShopQuantityGui.java"));for(String guard:new String[]{"h.service==s","h.owner.equals(player.getUniqueId())","h.batch==s.batchSize(h.item)","h.price==","if(!h.session.submit(player.getUniqueId()))return;int units=h.units","h.service.quoted(player,h.item,units,h.buy,h.batch,h.price)","getTopInventory()==h.inventory","event.setCancelled(true)","e.setCancelled(true)"})assertTrue(s.contains(guard),guard);assertTrue(s.contains("if(slot!=40)return"));assertFalse(s.contains("showDialog"));}
    @Test void automaticSelectionRetainsTheAcceptedBidBatchQuantityAndMoney(){var sale=TradeAmounts.selectSale(64,3,63,2);assertNotNull(sale);assertEquals(64,sale.batch());assertEquals(3,sale.price());assertEquals(43,sale.units());assertEquals(2,sale.money());assertEquals(2,TradeAmounts.quote(sale.batch(),sale.price(),sale.units(),false));assertEquals(1,TradeAmounts.quote(64,2,sale.units(),false));}
    @Test void noAutomaticSaleExistsForZeroBudgetOrUnpaidQuantity(){assertNull(TradeAmounts.selectSale(64,3,21,100));assertNull(TradeAmounts.selectSale(64,3,63,0));assertNull(TradeAmounts.selectSale(0,3,63,100));}
    @Test void frozenSaleCannotContainAnUnpaidOrInconsistentQuote(){assertThrows(IllegalArgumentException.class,()->new TradeAmounts.Sale(64,3,21,0));assertThrows(IllegalArgumentException.class,()->new TradeAmounts.Sale(64,3,43,3));assertThrows(IllegalArgumentException.class,()->new TradeAmounts.Sale(64,3,2305,100));}
    @Test void commandAllAndSellAllUseTheFrozenMaximumExecutor()throws Exception{String service=Files.readString(Path.of("src/main/java/ru/cherdakmd/diamondshop/ShopService.java"));assertTrue(service.contains("quoted(player,item,plan.units(),false,plan.batch(),plan.price())"));assertTrue(service.contains("var result=sellMaximum(player,item)"));String command=Files.readString(Path.of("src/main/java/ru/cherdakmd/diamondshop/ShopCommandHandler.java"));assertTrue(command.contains("all?plugin.shopService().sellMaximum(player,item)"));}
    @Test void buyWindowCannotAdvertiseOrApplyAMinimumBasedOnAsk()throws Exception{String s=Files.readString(Path.of("src/main/java/ru/cherdakmd/diamondshop/ShopQuantityGui.java"));assertTrue(s.contains("if(!h.buy)inv.setItem(33"));assertTrue(s.contains("case 33->h.buy?0:"));var yaml=org.bukkit.configuration.file.YamlConfiguration.loadConfiguration(new java.io.InputStreamReader(getClass().getResourceAsStream("/messages.yml"),java.nio.charset.StandardCharsets.UTF_8));var buy=yaml.getStringList("messages.quantity.buy-details");assertFalse(buy.isEmpty());assertFalse(buy.stream().anyMatch(line->line.contains("%minimum%")));assertTrue(yaml.getStringList("messages.quantity.details").stream().anyMatch(line->line.contains("%minimum%")));}

}
